        predicate: BedPredicate,
        predicates: BedPredicates,
        facts: BedFacts,
    ): Boolean =
        when (predicate) {
            BedPredicate.ON_SITE_CELL_CONNECTED -> predicates.onSiteCellConnected(facts)
            BedPredicate.RESERVATION_ENCOUNTER_OPEN -> predicates.reservationEncounterOpen(facts)
            BedPredicate.BED_RESTRICTIONS_ADMIT_PATIENT -> predicates.bedRestrictionsAdmitPatient(facts)
            BedPredicate.NO_ACTIVE_PRESSURE_ALARM -> predicates.noActivePressureAlarm(facts)
            BedPredicate.OVERRIDE_REASON_CHOSEN -> predicates.overrideReasonChosen(facts)
            BedPredicate.OCCUPANT_MATCHES_RESERVATION -> predicates.occupantMatchesReservation(facts)
            BedPredicate.NO_OVERLAPPING_OCCUPANCY -> predicates.noOverlappingOccupancy(facts)
            BedPredicate.NO_OPEN_OCCUPANCY -> predicates.noOpenOccupancy(facts)
            BedPredicate.REQUIRED_CLEAN_RECORDED -> predicates.requiredCleanRecorded(facts)
            BedPredicate.BLOCK_REASON_VALID -> predicates.blockReasonValid(facts)
            BedPredicate.REASON_ENTERED -> predicates.reasonEntered(facts)
            BedPredicate.RESERVED_ENCOUNTER_ENDED -> predicates.reservedEncounterEnded(facts)
            BedPredicate.CLEANING_NEEDED_ON_RETURN -> predicates.cleaningNeededOnReturn(facts)
            BedPredicate.NO_CLEANING_NEEDED_ON_RETURN -> predicates.noCleaningNeededOnReturn(facts)
            BedPredicate.PRIVILEGED_AND_AUDITED -> predicates.privilegedAndAudited(facts)
            BedPredicate.RETURNING_OCCUPANT_WAS_LAST_OCCUPANT -> predicates.returningOccupantWasLastOccupant(facts)
            BedPredicate.BACK_ENTERED_OCCUPANT_MATCHES -> predicates.backEnteredOccupantMatches(facts)
        }

    /** Applies [command] in [state] with [facts]; never changes state unless exactly one guard holds. */
    fun fire(
        state: BedState,
        command: BedCommand,
        predicates: BedPredicates,
        facts: BedFacts,
    ): Outcome<BedState, BedCommand, BedPredicate, BedEffect> = spec.fire(state, command) { holds(it, predicates, facts) }
}
